import torch
import numpy as np
import inspect

MAZE_PATH = './attachment/maze.pt'

def summarize(obj):
    if isinstance(obj, torch.Tensor):
        return f"Tensor, shape={tuple(obj.shape)}, dtype={obj.dtype}, first5={obj.flatten()[:5].tolist()}"
    elif isinstance(obj, np.ndarray):
        return f"np.ndarray, shape={obj.shape}, dtype={obj.dtype}, first5={obj.flatten()[:5]}"
    elif isinstance(obj, (list, tuple)):
        l = len(obj)
        preview = obj[:5] if l > 0 else []
        return f"{type(obj).__name__}, len={l}, first5={preview}"
    elif isinstance(obj, dict):
        l = len(obj)
        keys = list(obj.keys())[:5]
        return f"dict, len={l}, first5keys={keys}"
    elif isinstance(obj, (int, float, str, bool, type(None))):
        return f"{type(obj).__name__}, value={obj}"
    else:
        return f"{type(obj).__name__}"

def print_attr(obj, attr_name, prefix="  "):
    try:
        attr = getattr(obj, attr_name)
    except Exception as e:
        print(f"{prefix}{attr_name}: <error: {e}>")
        return
    print(f"{prefix}{attr_name} [{type(attr).__name__}]: {summarize(attr)}")
    # Special deeper inspection for _modules and _buffers
    if attr_name in ['_modules', '_buffers']:
        if attr:
            print(f"{prefix}  {attr_name} (detail):")
            for k, v in attr.items():
                print(f"{prefix}    {k}: {type(v).__name__}")
                if isinstance(v, torch.Tensor):
                    print(f"{prefix}      Tensor, shape={tuple(v.shape)}, dtype={v.dtype}, first5={v.flatten()[:5].tolist()}")

