obj = torch.load(MAZE_PATH, map_location='cpu')
print(f"Loaded object type: {type(obj)}")

# Step 2: Recursively inspect attributes, including private and inherited
attributes = set()
for cls in inspect.getmro(obj.__class__):
    attributes.update(cls.__dict__.keys())
attributes.update(dir(obj))

print("\n--- Attribute Summary ---")
for attr in sorted(attributes):
    if attr.startswith('__') and attr.endswith('__'):
        continue
    print_attr(obj, attr)

# Step 3: Extra, print representation for the object
print("\n--- repr(obj) ---\n", repr(obj))

