        except:
            pass

def try_decode(name):
    outputs = {}
    for b64fn in [base64.b64decode, base64.urlsafe_b64decode]:
        for add_padding in [False, True]:
            try:
                s = name
                if add_padding:
                    s += "=" * ((4 - len(s) % 4) % 4)
                decoded = b64fn(s)
                try:
                    as_ascii = decoded.decode('ascii')
                    outputs[f'{b64fn.__name__},ascii,pad={add_padding}'] = as_ascii
                except Exception:
                    outputs[f'{b64fn.__name__},bytes,pad={add_padding}'] = decoded
            except Exception:
                outputs[f'{b64fn.__name__},fail,pad={add_padding}'] = None
    return outputs

